import os

for rd in ["extracted/ipsw/ramdisk_erase", "extracted/ipsw/ramdisk_update"]:
    reg_files = 0
    dirs = 0
    symlinks = 0
    total_bytes = 0
    for root, dirnames, filenames in os.walk(rd, followlinks=False):
        dirs += len(dirnames)
        for d in dirnames:
            dp = os.path.join(root, d)
            if os.path.islink(dp):
                symlinks += 1
                dirs -= 1
        for f in filenames:
            fp = os.path.join(root, f)
            if os.path.islink(fp):
                symlinks += 1
            elif os.path.isfile(fp):
                reg_files += 1
                total_bytes += os.path.getsize(fp)
    print(f"{rd}: reg_files={reg_files}, subdirs={dirs}, symlinks={symlinks}, total_bytes={total_bytes:,}")
